from fastapi import FastAPI, Depends
import asyncio
import pytest
from fastapi.testclient import TestClient

class AsyncDep:
    async def __call__(self):
        return "async"

class GenDep:
    def __call__(self):
        yield "gen"

class AsyncGenDep:
    async def __call__(self):
        yield "async_gen"

app = FastAPI()

@app.get("/async")
async def root_async(dep = Depends(AsyncDep())):
    return {"dep": dep}

@app.get("/gen")
async def root_gen(dep = Depends(GenDep())):
    # For generators, FastAPI will iterate and take the first value if it's a dependency
    # Wait, if it's a generator, FastAPI will actually iterate it.
    # Let's see what happens.
    return {"dep": dep}

@app.get("/async_gen")
async def root_async_gen(dep = Depends(AsyncGenDep())):
    return {"dep": dep}

client = TestClient(app)

def test_async_dep_class():
    response = client.get("/async")
    assert response.status_code == 200
    assert response.json() == {"dep": "async"}

def test_gen_dep_class():
    response = client.get("/gen")
    assert response.status_code == 200
    # FastAPI's dependency resolution for generators:
    # If it's a generator, it will be executed.
    # Let's see what it returns.
    print(f"Gen response: {response.json()}")
    assert response.json() == {"dep": "gen"}

def test_async_gen_dep_class():
    response = client.get("/async_gen")
    assert response.status_code == 200
    print(f"AsyncGen response: {response.json()}")
    assert response.json() == {"dep": "async_gen"}

if __name__ == "__main__":
    try:
        test_async_dep_class()
        print("AsyncDep passed!")
        test_gen_dep_class()
        print("GenDep passed!")
        test_async_gen_dep_class()
        print("AsyncGenDep passed!")
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

